 public function testUnsignedAdminAndViewerCannotStartWorkflow():void{self::assertTrue(class_exists(Shop2ProductWorkflowPanel::class));wp_set_current_user(self::factory()->user->create(['role'=>'administrator']));self::assertWPError((new Shop2ProductWorkflowPanel())->process(['operation'=>'supplier_start','shop_key'=>'personalized_pod']));$owner=PortalAccessFixture::enroll();$id=self::factory()->user->create(['role'=>'administrator']);DigiForge\PortalAccess\Store::change($id,'Viewer',['personalized_pod'=>['research','personalized_pod','products','listings']],true,0,wp_generate_uuid4());PortalAccessFixture::login($id);DigiForge\PortalAccess\Session::start();self::assertWPError((new Shop2ProductWorkflowPanel())->process(['operation'=>'supplier_start','shop_key'=>'personalized_pod']));}
 public function testSnapshotReferenceCannotAdmitForeignOrCredentialQueryUrls():void{$url=add_query_arg(['df_view'=>'pod_personalized','df_shop'=>'personalized_pod','df_pi_snapshot'=>str_repeat('a',64)],set_url_scheme(home_url('/'),'https'));self::assertTrue(DigiForge\POD\Shop2ProductWorkflow::snapshotReference($url));foreach([$url.'&token=protected',$url.'&df_shop=personalized_pod',str_replace(parse_url($url,PHP_URL_HOST),'foreign.invalid',$url),$url.'#fragment'] as $bad)self::assertFalse(DigiForge\POD\Shop2ProductWorkflow::snapshotReference($bad));}
 private function png(int $shade,int $width=8,int $height=8,bool $density=false):string{$chunk=static fn($t,$d)=>pack('N',strlen($d)).$t.$d.hash('crc32b',$t.$d,true);return "\x89PNG\r\n\x1a\n".$chunk('IHDR',pack('NNCCCCC',$width,$height,8,2,0,0,0)).($density?$chunk('pHYs',pack('NNC',11811,11811,1)):'').$chunk('IDAT',gzcompress(str_repeat("\x00".str_repeat(chr($shade)."\x22\x33",$width),$height))).$chunk('IEND','');}
