 /** Synthetic sealed server receipts only: no HTTP, OAuth or live supplier acceptance. */
 private function receiptFixture(string $workflow,string $package,int $integration,string $operation,array $data,string $plan,?string $binding=null):string{$r=['status'=>'SUCCEEDED','workflow'=>$workflow,'package'=>$package,'integration_id'=>$integration,'operation'=>$operation,'data'=>$data,'shop_id'=>'12','connection_binding_hash'=>$binding,'plan_hash'=>$plan,'fixture'=>'SYNTHETIC_ISOLATED_NOT_PROVIDER_EVIDENCE'];$r['seal']=hash_hmac('sha256',DigiForge\Listings\Validator::canonicalJson($r),wp_salt('auth'));$raw=DigiForge\Listings\Validator::canonicalJson($r);$hash=hash('sha256',$raw);add_option('digiforge_pp_receipt_'.$hash,$raw,'',false);return $hash;}
}
